// Import of required libraries
import { test, expect, getBaseUrl, getValue, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { signIn, dismissProjectOwnerReminder, fillCollectionName, submitNewCollectionWizard, reopenNewCollectionWizard } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test.use({
    viewport: { width: 1280, height: 900 },
});


test('testUi', async ({ page }) => {
    test.setTimeout(118000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/admin/logout`);

    const playwrightRequest0: Record<string, any> = {
        "email": "admin@example.com",
        "password": "admin"
    };

    const response0 = await signIn(page, getValue(playwrightRequest0, "email"), getValue(playwrightRequest0, "password"));
    expect(response0.status()).toBe(200);

    await page.goto(`${baseUrl}/admin/content`);
    await dismissProjectOwnerReminder(page);
    await page.goto(`${baseUrl}/admin/settings/data-model/+`);

    // Collection names carry a UNIQUE constraint, so a fixed name would 409 on re-run.
    const playwrightRequest1: Record<string, any> = {"collection": `wizard_draft_reset_probe_${Date.now()}`};

    await fillCollectionName(page, getValue(playwrightRequest1, "collection"));
    const response1 = await submitNewCollectionWizard(page);
    expect(response1.status()).toBe(200);
    const createBody = await response1.json();
    expect(getValue(createBody, "data.collection")).toBe(getValue(playwrightRequest1, "collection"));
    expect(getValue(createBody, "data.meta.singleton")).toBe(false);

    await expect(page.getByRole("heading", { name: "Fields & Layout Saves" })).toBeVisible();

    await reopenNewCollectionWizard(page);
    // DR-UC02-P2: a successful create clears the draft, so the reopened wizard
    // starts empty and Next is gated off again.
    await expect(page.getByRole("textbox", { name: "A unique table name..." })).toHaveValue("");
    await expect(page.getByTestId("wizard-next-btn").getByRole("button", { name: "Next" })).toBeDisabled();
});
